func (u Type) JSONSize() (out int, _ error) {
	out++ // '{'
	switch u.typ {
	case "primitive":
		out += 18 // "type":"primitive"
		if u.primitive != nil {
			out += 13 // ,"primitive":
			unionVal := *u.primitive
			out += len(gjson.AppendJSONString(nil, string(unionVal.String())))
		}
	case "optional":
		out += 17 // "type":"optional"
		if u.optional != nil {
			out += 12 // ,"optional":
			unionVal := *u.optional
		}
	case "list":
		out += 13 // "type":"list"
		if u.list != nil {
			out += 8 // ,"list":
			unionVal := *u.list
		}
	case "set":
		out += 12 // "type":"set"
		if u.set != nil {
			out += 7 // ,"set":
			unionVal := *u.set
		}
	case "map":
		out += 12 // "type":"map"
		if u.map_ != nil {
			out += 7 // ,"map":
			unionVal := *u.map_
		}
	case "reference":
		out += 18 // "type":"reference"
		if u.reference != nil {
			out += 13 // ,"reference":
			unionVal := *u.reference
		}
	case "external":
		out += 17 // "type":"external"
		if u.external != nil {
			out += 12 // ,"external":
			unionVal := *u.external
		}
	default:
		out += 7 // "type":
		out += len(gjson.AppendJSONString(nil, u.typ))
	}
	out++ // '}'
	return out, nil
}

